      Lemma enter_loop : forall msF1 mo1 m1 m2 (r : rv) (ja jb junk1 junk2 : list byte),
        as_VIS H st0 msF1 = MS (mkRr r) F (Z_to_bv 64 0x106e78) fc None m2 (seg_rom asegs) ->
        as_AKREL H st0 (mkCfg msF1 mo1) -> as_MPRES H mo0 mo1 ->
        rsp r = spw -> rs1 r = spw -> rs0 r = Z_to_bv 64 (bv_unsigned sp) -> ra0 r = Z_to_bv 64 ff -> rs2 r = a2 -> rs3 r = a0 ->
        rs4 r = Z_to_bv 64 isk -> rs5 r = Z_to_bv 64 2147450880 -> rs7 r = Z_to_bv 64 q0 -> rgp r = gp -> rtp r = tp ->
        munch [(bv_unsigned sp - 304, bv_unsigned sp); (SPA, SPA + 184)] m0 m1 -> wmono asegs m0 m1 ->
        rw_cells asegs m1 SPA [CB 48 ja; C8 (Z_to_bv 64 0); CB 128 jb] ->
        rw_cells asegs m1 (bv_unsigned sp - 104) HI ->
        (SPA + 184 = bv_unsigned sp - 104 \/ (SPA + 200 = bv_unsigned sp - 104 /\ exists jg, rw_cells asegs m1 (SPA + 184) [CB 16 jg])) ->
        munch [(SPA - AFS_STACK, SPA); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + fsz 3); (sh ff, sh ff + fshn 3)] m1 m2 ->
        wmono asegs m1 m2 -> mem_inv asegs m2 -> stk asegs m2 lo SPA -> as_RFS H LF3 m2 ->
        rw_cells asegs m2 ff [CB 24 junk1; C8 spw; CB (Z.to_nat (fsz 3 - 40)) junk2; C8 (Z_to_bv 64 fp)] ->
        SHAD m2 ff (poison_bytes (Z.to_nat (fshn 3)) 0) -> rw_cells asegs m2 fp [C1 (b8 1)] -> ACONST m2 ->
        as_SR H POST (mkCfg msF1 mo1).
Proof.
